"use client";

import { Button } from "@/components/baseui/components/button";
import { toastManager } from "@/components/baseui/components/toast";

export default function Particle() {
	return (
		<Button
			variant="outline"
			size="sm"
			onClick={() => {
				toastManager.add({
					title: "Toast Title",
					description: "Toast description goes here",
				});
			}}
		>
			Click Here
		</Button>
	);
}
